//! The server must apply exactly the rules of the game (C#). Cases and expected answers come from
//! tests/fixtures/leaderboard.json, generated by tests/SnakeVs.Core.Tests/LeaderboardFixtureTests.cs.

use serde_json::Value;
use snakevs_api::rules::{self, Difficulty, Mode, Submission};

fn fixture() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/fixtures/leaderboard.json"
    );
    serde_json::from_str(&std::fs::read_to_string(path).expect("fixture missing"))
        .expect("fixture is not JSON")
}

fn submission(v: &Value) -> Submission {
    Submission {
        mode: Mode::parse(v["mode"].as_str().unwrap()).unwrap(),
        difficulty: Difficulty::parse(v["difficulty"].as_str().unwrap()).unwrap(),
        name: "RUN".into(),
        score: v["score"].as_i64().unwrap() as i32,
        apples: v["apples"].as_i64().unwrap() as i32,
        level: v["level"].as_i64().unwrap() as i32,
        steps: v["steps"].as_i64().unwrap(),
    }
}

#[test]
fn rule_numbers_match_the_game() {
    let r = &fixture()["rules"];
    let n = |k: &str| r[k].as_i64().unwrap_or_else(|| panic!("rules.{k} missing"));
    assert_eq!(n("boardWidth"), rules::BOARD_WIDTH);
    assert_eq!(n("boardHeight"), rules::BOARD_HEIGHT);
    assert_eq!(n("applesPerLevel"), rules::APPLES_PER_LEVEL);
    assert_eq!(
        n("endlessApplesPerSpeedStep"),
        rules::ENDLESS_APPLES_PER_SPEED_STEP
    );
    assert_eq!(n("appleScore"), rules::APPLE_SCORE);
    assert_eq!(n("appleScorePerLevel"), rules::APPLE_SCORE_PER_LEVEL);
    assert_eq!(n("goldenScore"), rules::GOLDEN_SCORE);
    assert_eq!(n("powerUpScore"), rules::POWER_UP_SCORE);
    assert_eq!(n("levelBonus"), rules::LEVEL_BONUS);
    assert_eq!(n("nameMaxLength"), rules::NAME_MAX_LENGTH as i64);
    assert_eq!(n("defaultTake"), rules::DEFAULT_TAKE);
    assert_eq!(n("maxTake"), rules::MAX_TAKE);
}

#[test]
fn names_are_normalized_like_the_game() {
    for case in fixture()["names"].as_array().unwrap() {
        let raw = case["raw"].as_str().unwrap();
        let expected = case["expected"].as_str();
        assert_eq!(
            rules::normalize_name(raw).as_deref(),
            expected,
            "name {raw:?}"
        );
    }
}

#[test]
fn plausibility_matches_the_game() {
    for case in fixture()["plausibility"].as_array().unwrap() {
        let expected = case["expected"].as_bool().unwrap();
        assert_eq!(
            rules::is_plausible(&submission(case)),
            expected,
            "case {case}"
        );
    }
}

#[test]
fn every_real_run_is_accepted() {
    let runs = fixture()["realRuns"].as_array().unwrap().clone();
    assert!(!runs.is_empty());
    for run in &runs {
        assert!(
            rules::is_plausible(&submission(run)),
            "real run rejected: {run}"
        );
    }
}
